// crates/server/src/main.rs
use axum::{Router, routing::{get, post}, extract::{State, Path}, Json};
use sqlx::PgPool;
use std::sync::Arc;

#[derive(Clone)]
struct AppState { db: PgPool, jwt_secret: Arc<String> }

async fn list_tasks(State(s): State<AppState>) -> Json<Vec<core::Task>> {
    let rows = sqlx::query_as::<_, core::Task>("SELECT id, title, done, created_at FROM tasks ORDER BY created_at DESC")
        .fetch_all(&s.db).await.unwrap();
    Json(rows)
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt::init();
    let db = PgPool::connect(&std::env::var("DATABASE_URL")?).await?;
    sqlx::migrate!("./migrations").run(&db).await?;

    let state = AppState { db, jwt_secret: Arc::new(std::env::var("JWT_SECRET")?) };
    let app = Router::new()
        .route("/health", get(|| async { "ok" }))
        .route("/tasks", get(list_tasks).post(create_task))
        .route("/tasks/:id", get(get_task).patch(update_task))
        .with_state(state);

    let listener = tokio::net::TcpListener::bind("0.0.0.0:3000").await?;
    axum::serve(listener, app).await?;
    Ok(())
}

